"""Small dependency-free observability UI served directly by FastAPI."""

from __future__ import annotations

DASHBOARD_HTML = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>PETLIBRO Local Relay</title><style>
:root{color-scheme:dark;--bg:#0e1319;--panel:#17212c;--panel-2:#101923;--line:#2c3a49;--text:#eef4f8;--muted:#91a2b3;--ok:#35bf82;--warn:#f0ad4e;--bad:#ed6b6b;--unknown:#8b98a6;--focus:#4b8fc4}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.45 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}header{padding:17px 24px 13px;border-bottom:1px solid var(--line);background:rgba(14,19,25,.98);position:sticky;top:0;z-index:5;backdrop-filter:blur(10px)}.head-row{display:flex;justify-content:space-between;gap:20px;align-items:flex-start}h1{font-size:21px;line-height:1.15;margin:0 0 11px}.build-meta{font-size:12px;color:var(--muted);white-space:nowrap}.status,.subnav,.toolbar{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.badge{display:inline-flex;gap:6px;align-items:center;border-radius:999px;padding:4px 9px;font-weight:600;font-size:12px;background:#24313e;color:var(--muted)}.badge::before{content:"●";font-size:10px}.state-online{color:var(--ok)}.state-connecting{color:var(--warn)}.state-offline{color:var(--bad)}.state-unknown{color:var(--unknown)}nav{display:flex;gap:5px;overflow-x:auto;padding:11px 20px;border-bottom:1px solid var(--line)}button,select,input,.nav-link{font:inherit}button,.nav-link{background:#263646;color:var(--text);border:1px solid #34485b;border-radius:6px;padding:7px 11px;cursor:pointer;text-decoration:none;display:inline-block}button:hover,.nav-link:hover{border-color:#5798c9}button.active,.nav-link.active{background:#3e7fae;border-color:#5da5d8}.raw-button{padding:4px 8px;font-size:12px;background:#1e2a35}.tab-section{display:none}.tab-section.active{display:block}main{max-width:1450px;margin:0 auto;padding:20px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(265px,1fr));gap:13px}.grid.wide{grid-template-columns:repeat(auto-fit,minmax(360px,1fr))}.card{background:var(--panel);border:1px solid var(--line);border-radius:8px;padding:15px;min-width:0}.card h2{font-size:15px;margin:0 0 11px}.card h3{font-size:13px;margin:14px 0 8px;color:var(--muted)}.card-head,.section-title,.device-page-title{display:flex;align-items:center;justify-content:space-between;gap:10px}.card-head{margin-bottom:10px}.card-head h2,.section-title h2,.device-page-title h2{margin:0}.section-title{margin:0 0 13px}.section-title h2{font-size:18px}.device-page-title{margin:0 0 15px;align-items:flex-start}.device-page-title h2{font-size:24px;line-height:1.1}.device-id{font:13px ui-monospace,SFMono-Regular,Menlo,monospace;color:var(--muted);margin-top:4px}.back-link{color:#a9d3ef;text-decoration:none;font-weight:600;margin-bottom:12px;display:inline-block}.subnav{padding:10px 0 16px;margin-bottom:16px;border-bottom:1px solid var(--line)}.subnav button{background:transparent;border:0;padding:5px 8px;color:var(--muted)}.subnav button.active{background:#263646;color:var(--text);border:1px solid #34485b}.kv{display:grid;grid-template-columns:minmax(105px,1fr) auto;gap:7px 15px;align-items:baseline}.kv dt{color:var(--muted)}.kv dd{margin:0;font-weight:600;text-align:right;max-width:260px;overflow-wrap:anywhere}.muted{color:var(--muted)}.warning-value{color:var(--warn)}.ok-value{color:var(--ok)}.metric-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:10px;margin:13px 0}.metric{background:var(--panel-2);border:1px solid var(--line);border-radius:7px;padding:10px}.metric .label{color:var(--muted);font-size:12px}.metric .number{font-size:20px;font-weight:700;margin-top:3px}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:7px}table{width:100%;border-collapse:collapse;min-width:620px}th,td{padding:9px 10px;text-align:left;border-bottom:1px solid var(--line);vertical-align:middle}th{font-size:11px;letter-spacing:.045em;text-transform:uppercase;color:var(--muted);background:#121b24}tr:last-child td{border-bottom:0}tr.device-row:hover{background:#1b2836}.device-link{color:var(--text);text-decoration:none;font-weight:600}.device-link:hover{color:#a9d3ef}.topic,.device-id{overflow-wrap:anywhere}.topic{font:12px ui-monospace,SFMono-Regular,Menlo,monospace}.empty{padding:18px;color:var(--muted);text-align:center}.timeline{border-left:2px solid var(--line);margin:4px 0 0 7px;padding-left:16px}.timeline-item{position:relative;padding:0 0 13px}.timeline-item::before{content:"";position:absolute;width:9px;height:9px;border-radius:50%;background:var(--unknown);left:-22px;top:5px}.timeline-item.online::before{background:var(--ok)}.timeline-item.connecting::before{background:var(--warn)}.timeline-item.offline::before{background:var(--bad)}.timeline-time{font:12px ui-monospace,SFMono-Regular,Menlo,monospace;color:var(--muted);margin-right:8px}.timeline-label{font-weight:700}.details{margin-top:10px}.details summary{cursor:pointer;color:#a9d3ef;font-size:12px}.details pre{margin:8px 0 0;padding:10px;background:#0b1016;border:1px solid var(--line);border-radius:6px;white-space:pre-wrap;overflow:auto;max-height:300px;font:12px ui-monospace,SFMono-Regular,Menlo,monospace}.rssi{font-weight:700}.rssi.excellent{color:var(--ok)}.rssi.good{color:#9ed48d}.rssi.weak{color:var(--warn)}.rssi.poor{color:var(--bad)}.toolbar{margin-bottom:10px}.toolbar label{color:var(--muted);font-size:12px}.toolbar select,.toolbar input{background:#101923;border:1px solid var(--line);border-radius:5px;color:var(--text);padding:6px 8px}.toolbar input{min-width:190px}.log-console{height:60vh;min-height:330px;overflow:auto;background:#090d12;border:1px solid var(--line);border-radius:7px;padding:9px;font:12px/1.55 ui-monospace,SFMono-Regular,Menlo,monospace}.log-line{display:grid;grid-template-columns:92px 70px 115px 1fr;gap:8px;white-space:pre-wrap;overflow-wrap:anywhere}.log-time{color:var(--muted)}.log-level{font-weight:700}.log-level.WARNING{color:var(--warn)}.log-level.ERROR,.log-level.CRITICAL{color:var(--bad)}.log-component{color:#91c8ec}.hidden{display:none!important}dialog{width:min(760px,92vw);color:var(--text);background:var(--panel);border:1px solid var(--line);border-radius:9px;padding:0}dialog::backdrop{background:rgba(0,0,0,.6)}.modal-head{display:flex;justify-content:space-between;align-items:center;padding:12px 14px;border-bottom:1px solid var(--line)}.modal-head h2{margin:0;font-size:15px}.modal-content{padding:14px;max-height:70vh;overflow:auto}.modal-content pre{margin:0;white-space:pre-wrap;overflow-wrap:anywhere;font:12px ui-monospace,SFMono-Regular,Menlo,monospace}.camera-placeholder{min-height:230px;display:grid;place-items:center;text-align:center;border:1px dashed #4b5e70;border-radius:8px;background:#0d151e;color:var(--muted);padding:25px}.camera-placeholder strong{display:block;color:var(--text);font-size:16px;margin-bottom:6px}.read-only{font-size:12px;color:var(--muted);margin-top:10px}.pill{font:12px ui-monospace,SFMono-Regular,Menlo,monospace;background:#1e2a35;border:1px solid var(--line);border-radius:5px;padding:2px 7px}@media(max-width:650px){header{padding:14px}.head-row{display:block}.build-meta{margin-top:9px}main{padding:13px}.grid,.grid.wide{grid-template-columns:1fr}.kv{grid-template-columns:1fr auto}.log-line{grid-template-columns:75px 63px 1fr}.log-component{display:none}.toolbar input{min-width:130px}.device-page-title{display:block}.device-page-title .status{margin-top:10px}}
.setting-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.setting-card{padding:18px}.setting-form{display:grid;gap:14px}.setting-form fieldset{display:grid;gap:14px;border:0;padding:0;margin:0;min-width:0}.setting-row{display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:34px}.setting-row label,.field-label{color:var(--muted);font-weight:600}.setting-row input[type=checkbox]{width:19px;height:19px;accent-color:var(--focus)}.setting-form select,.setting-form input:not([type=checkbox]):not([type=radio]),.schedule-form select,.schedule-form input:not([type=checkbox]):not([type=radio]){width:100%;padding:8px 10px;background:var(--panel-2);border:1px solid var(--line);border-radius:6px;color:var(--text)}.field{display:grid;gap:6px}.field-row{display:grid;grid-template-columns:1fr 1fr;gap:12px}.choice-row{display:flex;gap:8px;flex-wrap:wrap}.choice-row label,.day-selector label{display:flex;align-items:center;gap:6px;border:1px solid var(--line);border-radius:6px;padding:7px 9px;background:var(--panel-2);cursor:pointer}.choice-row input,.day-selector input{accent-color:var(--focus)}.range-row{display:grid;grid-template-columns:1fr 48px;gap:10px;align-items:center}.range-row output{color:var(--muted);text-align:right}.conditional{display:grid;gap:14px}.setting-actions{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:4px}.save-button{background:#3178a7;border-color:#519bd0}.save-button:disabled{opacity:.55;cursor:not-allowed}.status-message{font-size:12px;color:var(--muted);min-height:18px}.status-message.success{color:var(--ok)}.status-message.error{color:var(--bad)}.source-badge{font-size:11px;padding:3px 7px;border:1px solid var(--line);border-radius:999px;color:var(--muted)}.source-badge.local{color:var(--ok);border-color:#297354}.source-badge.diverged{color:var(--warn);border-color:#845d2e}.info-box{background:#102131;border:1px solid #294965;border-radius:8px;padding:13px 15px;color:#c6ddec;margin-bottom:16px}.info-box strong{display:block;color:var(--text);margin-bottom:3px}.schedule-toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:16px}.plan-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:13px}.plan-card{background:var(--panel);border:1px solid var(--line);border-radius:8px;padding:16px}.plan-time{font-size:25px;font-weight:700}.plan-meta{display:grid;gap:4px;color:var(--muted);margin:10px 0}.plan-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:13px}.plan-actions button.danger{color:#ffc1c1;border-color:#875050}.schedule-form{display:grid;gap:15px;background:var(--panel);border:1px solid var(--line);border-radius:8px;padding:18px;margin-bottom:16px}.schedule-form h3{margin:0;font-size:16px}.day-selector{display:flex;gap:6px;flex-wrap:wrap}.day-selector label{min-width:48px;justify-content:center;padding:7px}.empty-plan{padding:28px;border:1px dashed var(--line);border-radius:8px;color:var(--muted);text-align:center}@media(max-width:850px){.setting-grid{grid-template-columns:1fr}}@media(max-width:520px){.field-row{grid-template-columns:1fr}.setting-row{align-items:flex-start;flex-direction:column;gap:6px}.schedule-toolbar{align-items:flex-start;flex-direction:column}.plan-list{grid-template-columns:1fr}}
</style></head><body>
<header><div class="head-row"><div><h1>PETLIBRO Local Relay</h1><div class="status" id="header-badges">Loading…</div></div><div class="build-meta" id="build-meta">—</div></div></header>
<nav id="tabs" aria-label="Dashboard sections"></nav><main id="global-pages">
<section id="Overview" class="tab-section active"></section><section id="Cloud" class="tab-section"></section><section id="Devices" class="tab-section"></section><section id="Queues" class="tab-section"></section><section id="State" class="tab-section"></section><section id="NTP" class="tab-section"></section><section id="Logs" class="tab-section"></section><section id="System" class="tab-section"></section>
</main><main id="device-page" class="hidden"></main>
<dialog id="raw-modal"><div class="modal-head"><h2>Raw JSON</h2><button id="raw-close" type="button">Close</button></div><div class="modal-content"><pre id="raw-content"></pre></div></dialog>
<script>
const TAB_NAMES=['Overview','Cloud','Devices','Queues','State','NTP','Logs','System'];
const DEVICE_TABS=['overview','controls','schedule','camera','state','logs'];
const GLOBAL_ROUTES={Overview:'/',Cloud:'/cloud',Devices:'/devices',Queues:'/queues',State:'/state',NTP:'/ntp',Logs:'/logs',System:'/system'};
const runtime={active:tabForPath(window.location.pathname),raw:new Map(),rawId:0,logs:[],paused:false,autoScroll:true,logEventSource:null,devices:[],selected:null,deviceDetail:null,deviceTab:deviceTabFromHash(),soundSaving:false,soundFeedback:null,motionSaving:false,motionFeedback:null,controlFeedback:{},controlSaving:{},controlDrafts:{},draftDeviceId:null,scheduleEditor:null,scheduleFeedback:null};
const byId=id=>document.getElementById(id);
const escapeHtml=value=>String(value??'—').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const fetchJson=async path=>{const response=await fetch(path);if(!response.ok)throw new Error(`HTTP ${response.status}`);return response.json()};
function safeDecode(value){try{return decodeURIComponent(value)}catch(error){return null}}
function currentDeviceId(){const parts=window.location.pathname.split('/').filter(Boolean);return parts.length===2&&parts[0]==='devices'?safeDecode(parts[1]):null}
function tabForPath(pathname){return Object.entries(GLOBAL_ROUTES).find(([,path])=>path===pathname)?.[0]||'Overview'}
function deviceTabFromHash(){const tab=window.location.hash.slice(1).toLowerCase();return DEVICE_TABS.includes(tab)?tab:'overview'}
function epochSeconds(value){if(value===null||value===undefined||value==='')return null;const number=Number(value);if(!Number.isFinite(number))return null;return number>100000000000?number/1000:number}
function formatDuration(seconds){if(seconds===null||seconds===undefined||!Number.isFinite(Number(seconds)))return '—';let value=Math.max(0,Math.floor(Number(seconds)));const days=Math.floor(value/86400);value%=86400;const hours=Math.floor(value/3600);value%=3600;const minutes=Math.floor(value/60);value%=60;const parts=[];if(days)parts.push(`${days}d`);if(hours||days)parts.push(`${hours}h`);if(minutes||hours||days)parts.push(`${minutes}m`);parts.push(`${value}s`);return parts.join(' ')}
function formatAge(timestamp){const seconds=epochSeconds(timestamp);return seconds===null?'—':formatDuration(Date.now()/1000-seconds)+' ago'}
function formatTimestamp(timestamp){const seconds=epochSeconds(timestamp);return seconds===null?'—':new Date(seconds*1000).toLocaleString(undefined,{hour:'2-digit',minute:'2-digit',second:'2-digit',year:'numeric',month:'short',day:'2-digit'})}
function formatTime(timestamp){const seconds=epochSeconds(timestamp);return seconds===null?'—':new Date(seconds*1000).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit',second:'2-digit'})}
function formatPercent(value){return value===null||value===undefined?'—':`${Math.round(Number(value)*100)} %`}
function formatBoolean(value){return value===true?'Enabled':value===false?'Disabled':'—'}
function formatBytes(value){if(value===null||value===undefined)return '—';const units=['B','KB','MB','GB','TB'];let size=Number(value),index=0;while(size>=1024&&index<units.length-1){size/=1024;index++}return `${size.toFixed(index?1:0)} ${units[index]}`}
function statusClass(state){const normalized=String(state||'UNKNOWN').toUpperCase();if(normalized==='ONLINE'||normalized==='RUNNING'||normalized==='ACTIVE')return 'state-online';if(normalized.includes('CONNECTING')||normalized==='PENDING')return 'state-connecting';if(normalized==='SUSPENDED')return 'state-unknown';if(normalized==='DISCONNECTED'||normalized==='OFFLINE'||normalized==='ERROR')return 'state-offline';return 'state-unknown'}
function statusBadge(state,label){const text=String(state||'UNKNOWN').replaceAll('_',' ');return `<span class="badge ${statusClass(state)}">${escapeHtml(label||text)}${label?`: ${escapeHtml(text)}`:''}</span>`}
function rawButton(value,label='View raw JSON'){const id=String(++runtime.rawId);runtime.raw.set(id,value);return `<button type="button" class="raw-button" data-raw-id="${id}">${escapeHtml(label)}</button>`}
function bindRawButtons(){document.querySelectorAll('[data-raw-id]').forEach(button=>{button.onclick=()=>openRaw(runtime.raw.get(button.dataset.rawId))})}
function openRaw(value){byId('raw-content').textContent=JSON.stringify(value,null,2);byId('raw-modal').showModal()}
function card(title,content,extra=''){return `<article class="card">${extra?`<div class="card-head"><h2>${escapeHtml(title)}</h2>${extra}</div>`:`<h2>${escapeHtml(title)}</h2>`}${content}</article>`}
function kv(rows){return `<dl class="kv">${rows.map(([key,value,klass])=>`<dt>${escapeHtml(key)}</dt><dd${klass?` class="${escapeHtml(klass)}"`:''}>${value}</dd>`).join('')}</dl>`}
function metric(label,value,klass=''){return `<div class="metric"><div class="label">${escapeHtml(label)}</div><div class="number ${escapeHtml(klass)}">${escapeHtml(value)}</div></div>`}
function table(headers,rows,empty='No data'){if(!rows.length)return `<div class="empty">${escapeHtml(empty)}</div>`;return `<div class="table-wrap"><table><thead><tr>${headers.map(header=>`<th>${escapeHtml(header)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`}
function scalar(value){if(value===true||value===false)return escapeHtml(formatBoolean(value));if(value===null||value===undefined)return '—';if(typeof value==='object')return '<span class="muted">Object</span>';return escapeHtml(value)}
function payloadMsgId(payload){return payload&&typeof payload==='object'&&typeof payload.msgId==='string'?payload.msgId:'—'}
function rssiMarkup(value){if(value===null||value===undefined)return '—';const rssi=Number(value);const quality=rssi>-50?'excellent':rssi>-60?'good':rssi>-70?'weak':'poor';return `<span class="rssi ${quality}">${escapeHtml(`${rssi} dBm · ${quality}`)}</span>`}
function setupTabs(){const deviceId=currentDeviceId();const fleetActive=runtime.active==='Devices'||deviceId!==null;byId('tabs').innerHTML=TAB_NAMES.map(name=>`<a href="${GLOBAL_ROUTES[name]}" data-route="${GLOBAL_ROUTES[name]}" class="nav-link ${(name==='Devices'?fleetActive:runtime.active===name&&!deviceId)?'active':''}">${escapeHtml(name)}</a>`).join('')}
function showTab(name){navigate(GLOBAL_ROUTES[name])}
function navigate(path){history.pushState(null,'',path);applyRoute()}
function applyRoute(){runtime.active=tabForPath(window.location.pathname);runtime.deviceTab=deviceTabFromHash();const deviceId=currentDeviceId();if(!deviceId)clearEditingDrafts();TAB_NAMES.forEach(tab=>byId(tab).classList.toggle('active',!deviceId&&tab===runtime.active));setupTabs();refresh()}
function bindRoutes(){document.addEventListener('click',event=>{const link=event.target.closest('a[data-route]');if(!link)return;event.preventDefault();navigate(link.dataset.route)})}
function renderHeader(status,system){const summary=status.devices;byId('header-badges').innerHTML=[statusBadge('RUNNING','Relay'),statusBadge(status.local_mqtt.connected?'ONLINE':'OFFLINE','Local MQTT'),statusBadge(summary.local_online?'ONLINE':'OFFLINE',`Devices ${summary.local_online}/${summary.known} local`),statusBadge(summary.cloud_online?'ONLINE':'OFFLINE',`PETLIBRO ${summary.cloud_online}/${summary.bridged} online`)].join('');const backlog=status.queues.pending_total?` · ${status.queues.pending_total} queued`:'';byId('build-meta').textContent=`Uptime ${formatDuration(status.relay.uptime_seconds)} · ${system.version} · ${system.git_commit}${backlog}`}
function renderOverview(status){const summary=status.devices,responder=status.local_responder,queues=status.queues;byId('Overview').innerHTML=`<div class="section-title"><h2>Overview</h2>${statusBadge(status.relay.status,'Relay')}</div><div class="metric-grid">${metric('Devices known',summary.known)}${metric('Local online',summary.local_online,summary.local_online?'ok-value':'')}${metric('Cloud online',summary.cloud_online,summary.cloud_online?'ok-value':'')}${metric('Cloud degraded',summary.cloud_degraded,summary.cloud_degraded?'warning-value':'')}${metric('Cloud suspended',summary.cloud_suspended||0)}${metric('Queues pending',queues.pending_total,queues.pending_total?'warning-value':'ok-value')}</div><div class="grid wide">${card('Relay',kv([['Status','<span class="ok-value">Running</span>'],['Mode',escapeHtml(status.relay.mode==='PURE_PIPE'?'Pure pipe':'Local fallback')],['Uptime',escapeHtml(formatDuration(status.relay.uptime_seconds))],['Local MQTT',statusBadge(status.local_mqtt.connected?'ONLINE':'OFFLINE')],['Auto-enrollment',escapeHtml(formatBoolean(status.relay.auto_enroll))]]))}${card('Devices',kv([['Known',escapeHtml(summary.known)],['Bridged',escapeHtml(summary.bridged)],['Awaiting enrollment',escapeHtml(summary.awaiting_enrollment),summary.awaiting_enrollment?'warning-value':''],['Local online',escapeHtml(`${summary.local_online} / ${summary.known}`)],['Cloud online',escapeHtml(`${summary.cloud_online} / ${summary.bridged}`)],['Suspended (device away)',escapeHtml(summary.cloud_suspended||0)]]))}${card('Queues',kv([['Pending total',escapeHtml(queues.pending_total),queues.pending_total?'warning-value':'ok-value'],['Devices with backlog',escapeHtml(Object.values(queues.pending_by_device||{}).filter(Number).length)],['Unroutable rows',escapeHtml(queues.unroutable||0),queues.unroutable?'warning-value':'ok-value']]))}${card('Local responder',kv([['Global',escapeHtml(formatBoolean(responder.enabled))],['NTP',escapeHtml(formatBoolean(responder.ntp_enabled))],['Config',escapeHtml(formatBoolean(responder.config_enabled))],['Feeding plan',escapeHtml(formatBoolean(responder.feeding_plan_enabled))]]))}</div>`}
function eventPresentation(event){const kind=String(event.kind||'');if(kind==='upstream_online')return ['ONLINE','online'];if(kind==='upstream_restored')return ['RESTORED','online'];if(kind==='upstream_session_lost')return ['SESSION LOST','offline'];if(kind==='upstream_connect_attempt')return ['MQTT CONNECTING','connecting'];if(kind==='upstream_retry_failed'||kind==='upstream_tcp_connect_failed'||kind==='upstream_connack_refused')return ['RETRY FAILED','connecting'];return [kind.replaceAll('_',' ').toUpperCase(),'unknown']}
function upstreamCard(entry){const up=entry.upstream,c=up.counters||{};return `<article class="card"><div class="card-head"><h2>${escapeHtml(entry.device_id)}</h2>${statusBadge(up.state)}</div><div class="metric-grid">${metric('15 minutes',formatPercent(up.availability?.['15m']))}${metric('1 hour',formatPercent(up.availability?.['1h']))}${metric('24 hours',formatPercent(up.availability?.['24h']))}</div><h3>Sessions</h3>${kv([['Current session',escapeHtml(formatDuration(up.current_online_duration_seconds))],['Previous session',escapeHtml(formatDuration(up.previous_session_duration_seconds))],['Sessions lost',escapeHtml(c.sessions_lost||0),c.sessions_lost?'warning-value':''],['Connect attempts',escapeHtml(c.connect_attempts||0)],['CONNACK timeouts',escapeHtml(c.connack_timeouts||0),c.connack_timeouts?'warning-value':''],['TCP failures',escapeHtml(c.tcp_connect_failures||0),c.tcp_connect_failures?'warning-value':'']])}</article>`}
function timelineMarkup(events,emptyText){const ordered=events.filter(event=>String(event.kind).startsWith('upstream')).reverse();if(!ordered.length)return `<div class="empty">${escapeHtml(emptyText)}</div>`;return `<div class="timeline">${ordered.map(event=>{const [label,kind]=eventPresentation(event);const who=event.device_id?`<span class="pill">${escapeHtml(event.device_id)}</span> `:'';return `<div class="timeline-item ${kind}"><span class="timeline-time">${escapeHtml(formatTime(event.timestamp))}</span>${who}<span class="timeline-label">${escapeHtml(label)}</span><div class="muted">${escapeHtml(event.message)}</div></div>`}).join('')}</div>`}
function renderCloud(cloud){const cards=cloud.devices.map(upstreamCard).join('');byId('Cloud').innerHTML=`<div class="section-title"><h2>Cloud</h2><span class="muted">One PETLIBRO session per device</span></div>${cards?`<div class="grid wide">${cards}</div>`:'<div class="empty">No device has opened an upstream session yet.</div>'}${card('Recent upstream timeline',timelineMarkup(cloud.events,'No upstream events recorded yet.'))}`}
function deviceRow(item){const path=`/devices/${encodeURIComponent(item.device_id)}`;return `<tr class="device-row"><td><a class="device-link" href="${path}" data-route="${path}">${escapeHtml(item.product_id)} · ${escapeHtml(item.device_id)}</a></td><td>${statusBadge(item.local_state==='LOCAL_ONLINE'?'ONLINE':'OFFLINE')}</td><td>${item.bridged?statusBadge(item.cloud_state):'<span class="muted">Not bridged</span>'}</td><td>${rssiMarkup(item.rssi)}</td><td>${escapeHtml(item.queue_pending)}</td><td>${escapeHtml(formatAge(item.last_seen_at))}</td></tr>`}
function fleetData(payload){if(!payload||!Array.isArray(payload.devices)||!payload.summary||typeof payload.summary!=='object')throw new Error('Invalid /api/devices response');return payload}
function renderDevices(payload){const devices=fleetData(payload);runtime.devices=devices.devices;const summary=devices.summary;byId('Devices').innerHTML=`<div class="section-title"><h2>Devices</h2><span class="muted">${escapeHtml(`${summary.bridged} bridged · ${summary.known} known`)}</span></div>${table(['Device','Local','Cloud','RSSI','Queue','Last seen'],runtime.devices.map(deviceRow),'No devices known yet. Waiting for a PETLIBRO device to connect to the local relay.')}`}
function devicePicker(){const options=runtime.devices.map(item=>`<option value="${escapeHtml(item.device_id)}"${item.device_id===runtime.selected?' selected':''}>${escapeHtml(`${item.product_id} · ${item.device_id}`)}</option>`).join('');return `<div class="toolbar"><label>Device <select id="device-select">${options}</select></label><span class="muted">Scoped to one device</span></div>`}
function bindDevicePicker(){const select=byId('device-select');if(select)select.onchange=()=>{runtime.selected=select.value;refresh()}}
function queueRows(queue){return queue.messages.map(item=>`<tr><td>${escapeHtml(formatTime(item.created_at))}</td><td>${escapeHtml(queue.direction==='local-to-upstream'?'Device → Cloud':'Cloud → Device')}</td><td>${escapeHtml(item.cmd||'—')}</td><td>${escapeHtml(payloadMsgId(item.payload))}</td><td>${escapeHtml(formatDuration(item.age_seconds))}</td><td>${escapeHtml(item.replay_policy)}</td><td>${statusBadge('PENDING')}</td><td><details class="details"><summary>Topic</summary><div class="topic">${escapeHtml(item.topic)}</div></details>${rawButton(item.payload,'View JSON')}</td></tr>`) }
function queueCard(title,queue){return card(title,`<div class="metric-grid">${metric('Pending',queue.pending,queue.pending?'warning-value':'ok-value')}${metric('Oldest',formatDuration(queue.oldest_age_seconds))}${metric('Newest',formatDuration(queue.newest_age_seconds))}</div>${table(['Time','Direction','CMD','Msg ID','Age','Policy','Status','Debug'],queueRows(queue),'Queue is empty.')}`,queue.pending?statusBadge('PENDING','Backlog'):statusBadge('ONLINE','Clear'))}
function queuesMarkup(queues){return `<div class="grid wide">${queueCard('Device → Cloud',queues.device_to_cloud)}${queueCard('Cloud → Device',queues.cloud_to_device)}</div>`}
function renderQueues(queues){byId('Queues').innerHTML=`<div class="section-title"><h2>Queues</h2><span class="muted">Durable SQLite queues, per device</span></div>${devicePicker()}${queuesMarkup(queues)}`;bindDevicePicker();bindRawButtons()}
function stateRows(rows){return rows.map(item=>`<tr><td>${escapeHtml(item.key)}</td><td>${scalar(item.value)}</td><td>${escapeHtml(formatTimestamp(item.updated_at))}</td><td>${escapeHtml(formatAge(item.updated_at))}</td><td>${typeof item.value==='object'?rawButton(item.value,'View JSON'):''}</td></tr>`)}
function stateMarkup(state){const plan=state.feeding_plans;const rawRows=state.raw_messages.map(item=>`<tr><td class="topic">${escapeHtml(item.topic)}</td><td>${escapeHtml(item.cmd||'—')}</td><td>${escapeHtml(formatTimestamp(item.updated_at))}</td><td>${rawButton(item.payload,'View JSON')}</td></tr>`);return `<div class="grid wide">${card('Reported state',table(['Key','Value','Updated','Age','Debug'],stateRows(state.reported),'No reported state.'))}${card('Cloud desired',table(['Key','Value','Updated','Age','Debug'],stateRows(state.desired),'No cloud desired state.'))}${card('Feeding plan',kv([['Status',plan.complete?'<span class="ok-value">Cached ✓</span>':'<span class="muted">Not cached</span>'],['Updated',escapeHtml(formatTimestamp(plan.updated_at))],['Source message ID',escapeHtml(plan.source_msg_id)],['Plans',escapeHtml(plan.plans?.length||0)]])+(plan.complete?`<div class="details">${rawButton(plan.plans,'View raw JSON')}</div>`:''))}</div>${card('Raw messages',table(['Topic','CMD','Updated','Debug'],rawRows,'No raw messages cached.'))}`}
function renderState(state){byId('State').innerHTML=`<div class="section-title"><h2>State shadow</h2><span class="muted">Last-known values only</span></div>${devicePicker()}${stateMarkup(state)}`;bindDevicePicker();bindRawButtons()}
function ntpMarkup(ntp,responder){const timezone=responder.device_timezone||'—';return `<div class="grid wide">${card('NTP observer',kv([['Last request',escapeHtml(formatTimestamp(ntp.last_request?.updated_at))],['Trigger',escapeHtml(String(ntp.trigger||'').replaceAll('_',' '))],['Requests observed',escapeHtml(ntp.requests_observed)],['Cloud responses',escapeHtml(ntp.cloud_ntp_sync_responses)],['Local responses',escapeHtml(ntp.local_ntp_responses)],['Local fallback',escapeHtml(formatBoolean(ntp.local_fallback_enabled))]]))}${card('Timezone',kv([['Timezone',escapeHtml(timezone)],['Current offset','—'],['DST','—']]))}</div>${card('NTP debug',`<div class="toolbar">${ntp.last_request?rawButton(ntp.last_request.payload,'View request raw JSON'):''}${ntp.last_ntp_sync?rawButton(ntp.last_ntp_sync.payload,'View response raw JSON'):''}</div>`)}`}
function renderNtp(ntp,status){byId('NTP').innerHTML=`<div class="section-title"><h2>NTP Observer</h2>${statusBadge(ntp.local_fallback_enabled?'ONLINE':'DISABLED','Local fallback')}</div>${devicePicker()}${ntpMarkup(ntp,status.local_responder)}`;bindDevicePicker();bindRawButtons()}
function renderSystem(system,status){const rows=system.databases.map(item=>`<tr><td>${escapeHtml(item.name)}</td><td>${escapeHtml(formatBytes(item.size_bytes))}</td><td class="topic">${escapeHtml(item.path)}</td></tr>`);const runtimeData=system.runtime||{},memory=runtimeData.memory||{},disk=runtimeData.disk||{};byId('System').innerHTML=`<div class="section-title"><h2>System</h2><span class="muted">Local process diagnostics</span></div><div class="grid wide">${card('Application',kv([['Version',escapeHtml(system.version)],['Commit',escapeHtml(system.git_commit)],['Python',escapeHtml(system.python_version)],['Hostname',escapeHtml(system.hostname)],['Uptime',escapeHtml(formatDuration(status.relay.uptime_seconds))]]))}${card('Runtime',kv([['CPU load (1m)',escapeHtml(runtimeData.cpu_load_1m===null||runtimeData.cpu_load_1m===undefined?'—':Number(runtimeData.cpu_load_1m).toFixed(2))],['Memory',memory.total_bytes?escapeHtml(`${formatBytes(memory.used_bytes)} / ${formatBytes(memory.total_bytes)}`):'—'],['Disk',disk.total_bytes?escapeHtml(`${formatBytes(disk.used_bytes)} / ${formatBytes(disk.total_bytes)}`):'—']]))}${card('Storage',table(['Database','Size','Path'],rows,'No database metadata.'))}</div>`}
function logPanel(prefix,fixedDevice){const fixed=fixedDevice?'<span class="muted">Scoped to this device</span>':`<label>Device <select id="${prefix}-device"><option value="">All</option></select></label>`;return `<div class="toolbar"><label>Level <select id="${prefix}-level"><option value="">All</option><option>DEBUG</option><option>INFO</option><option>WARNING</option><option>ERROR</option></select></label><label>Component <select id="${prefix}-component"><option value="">All</option></select></label>${fixed}<label>CMD <select id="${prefix}-cmd"><option value="">All</option></select></label><label>Search <input id="${prefix}-search" type="search" placeholder="Search logs"></label><button id="${prefix}-pause" type="button">Pause</button><button id="${prefix}-scroll" type="button">Auto-scroll: On</button></div><div class="log-console" id="${prefix}-console" aria-live="polite"></div>`}
function initializeLogControls(prefix,fixedDevice){for(const name of ['level','component','cmd','search']){const element=byId(`${prefix}-${name}`);if(element)element.addEventListener('input',()=>renderLogLines(prefix,fixedDevice))}const device=byId(`${prefix}-device`);if(device)device.addEventListener('input',()=>renderLogLines(prefix,null));const pause=byId(`${prefix}-pause`);if(pause)pause.onclick=()=>{runtime.paused=!runtime.paused;pause.textContent=runtime.paused?'Resume':'Pause';if(!runtime.paused)renderLogLines(prefix,fixedDevice)};const scroll=byId(`${prefix}-scroll`);if(scroll)scroll.onclick=()=>{runtime.autoScroll=!runtime.autoScroll;scroll.textContent=`Auto-scroll: ${runtime.autoScroll?'On':'Off'}`}}
function logFilters(prefix,fixedDevice){return {level:byId(`${prefix}-level`)?.value||'',component:byId(`${prefix}-component`)?.value||'',device:fixedDevice||byId(`${prefix}-device`)?.value||'',cmd:byId(`${prefix}-cmd`)?.value||'',search:(byId(`${prefix}-search`)?.value||'').toLowerCase()}}
function matchesLog(item,prefix,fixedDevice){const filters=logFilters(prefix,fixedDevice);return (!filters.level||item.level===filters.level)&&(!filters.component||item.component===filters.component)&&(!filters.device||item.device_id===filters.device)&&(!filters.cmd||item.cmd===filters.cmd)&&(!filters.search||`${item.message} ${item.component} ${item.device_id||''} ${item.cmd||''}`.toLowerCase().includes(filters.search))}
function addFilterOption(prefix,name,value){const select=byId(`${prefix}-${name}`);if(!select||!value||Array.from(select.options).some(option=>option.value===value))return;const option=document.createElement('option');option.value=value;option.textContent=value;select.append(option)}
function appendLog(item){if(runtime.logs.some(existing=>existing.sequence===item.sequence))return;runtime.logs.push(item);if(runtime.logs.length>1000)runtime.logs.shift();for(const prefix of ['log','device-log']){addFilterOption(prefix,'component',item.component);addFilterOption(prefix,'device',item.device_id);addFilterOption(prefix,'cmd',item.cmd)}if(!runtime.paused){renderLogLines('log',null);const deviceId=currentDeviceId();if(deviceId)renderLogLines('device-log',deviceId)}}
function renderLogLines(prefix,fixedDevice){const consoleElement=byId(`${prefix}-console`);if(!consoleElement)return;consoleElement.textContent='';runtime.logs.filter(item=>matchesLog(item,prefix,fixedDevice)).forEach(item=>{const line=document.createElement('div');line.className='log-line';line.innerHTML='<span class="log-time"></span><span class="log-level"></span><span class="log-component"></span><span class="log-message"></span>';line.querySelector('.log-time').textContent=new Date(item.timestamp*1000).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit',second:'2-digit',fractionalSecondDigits:3});const level=line.querySelector('.log-level');level.textContent=item.level;level.classList.add(item.level);line.querySelector('.log-component').textContent=item.component;line.querySelector('.log-message').textContent=item.message;consoleElement.append(line)});if(runtime.autoScroll)consoleElement.scrollTop=consoleElement.scrollHeight}
function renderLogs(){byId('Logs').innerHTML=`<div class="section-title"><h2>Logs</h2><span class="muted">Live SSE stream</span></div>${logPanel('log',null)}`;initializeLogControls('log',null);runtime.logs.forEach(item=>{addFilterOption('log','component',item.component);addFilterOption('log','device',item.device_id);addFilterOption('log','cmd',item.cmd)});renderLogLines('log',null)}
async function loadInitialLogs(){const response=await fetchJson('/api/logs?limit=500');response.entries.forEach(appendLog)}
function startLogStream(){if(runtime.logEventSource)return;runtime.logEventSource=new EventSource('/api/logs/stream');runtime.logEventSource.addEventListener('log',event=>appendLog(JSON.parse(event.data)));runtime.logEventSource.onerror=()=>{runtime.logEventSource?.close();runtime.logEventSource=null;setTimeout(startLogStream,3000)}}
function desiredValues(state){return Object.fromEntries((state.desired||[]).map(item=>[item.key,item.value]))}
function controlValue(values,key){const value=values[key];return value===undefined?'—':scalar(value)}
function confirmedValues(state){return Object.fromEntries((state.local_confirmed||[]).map(item=>[item.key,item.value]))}
function controlToggleMarkup(title,label,id,controlName,state,controls,saving,feedback){const desired=desiredValues(state),confirmed=confirmedValues(state),capability=controls?.[controlName]||{},value=confirmed[controlName]??desired[controlName];const enabled=capability.writable&&capability.device_online&&capability.required_state_available&&!capability.pending&&!saving;const buttonLabel=saving?'Saving…':value===true?'ON':'OFF';const message=feedback?`<div class="read-only ${feedback.error?'warning-value':'ok-value'}">${escapeHtml(feedback.message)}</div>`:'';return card(title,`<div class="kv"><dt>${escapeHtml(label)}</dt><dd><button type="button" id="${escapeHtml(id)}" ${enabled?'':'disabled'}>${escapeHtml(buttonLabel)}</button></dd></div>${message}`)}
function soundControlMarkup(state,controls){return controlToggleMarkup('Audio','Device sound','sound-switch-toggle','soundSwitch',state,controls,runtime.soundSaving,runtime.soundFeedback)}
function motionControlMarkup(state,controls){const values=desiredValues(state);return `${controlToggleMarkup('Motion detection','Detection','motion-detection-switch-toggle','motionDetectionSwitch',state,controls,runtime.motionSaving,runtime.motionFeedback)}${card('Motion detection details',kv([['Sensitivity',controlValue(values,'motionDetectionSensitivity')],['Range',controlValue(values,'motionDetectionRange')],['Aging type',controlValue(values,'motionDetectionAgingType')]]))}`}
function groupForm(title,path,state,fields){const desired=desiredValues(state),confirmed=confirmedValues(state),values={...desired,...confirmed};const diverged=fields.some(([key])=>Object.hasOwn(confirmed,key)&&Object.hasOwn(desired,key)&&confirmed[key]!==desired[key]);const rows=fields.map(([key,label,type,options])=>{const known=Object.hasOwn(values,key),value=values[key],knownAttr=`data-known="${known?'true':'false'}"`;if(type==='boolean')return `<label>${escapeHtml(label)}<input type="checkbox" name="${escapeHtml(key)}" ${knownAttr} ${value===true?'checked':''}></label>`;if(type==='select'){const placeholder=known?'':'<option value="" selected disabled>Select…</option>';return `<label>${escapeHtml(label)}<select name="${escapeHtml(key)}" ${knownAttr}>${placeholder}${options.map(option=>`<option ${value===option?'selected':''}>${escapeHtml(option)}</option>`).join('')}</select></label>`}return `<label>${escapeHtml(label)}<input type="${type}" name="${escapeHtml(key)}" ${knownAttr} value="${escapeHtml(value??'')}"></label>`}).join('');return card(title,`<form class="group-form" data-control-path="${escapeHtml(path)}">${rows}<button type="submit">Save</button><div class="read-only">Saves only after feeder ACK.</div>${diverged?'<div class="read-only warning-value">Local confirmation differs from cloud desired.</div>':''}</form>`)}
function controlsMarkup(state,controls){const values=desiredValues(state);return `<div class="grid wide">${motionControlMarkup(state,controls)}${groupForm('Motion settings','motion',state,[['motionDetectionAgingType','Schedule type','select',['1','2']],['motionDetectionStartTime','Start','time'],['motionDetectionEndTime','End','time'],['motionDetectionSensitivity','Sensitivity','select',['LOW','MEDIUM','HIGH']],['motionDetectionRange','Range','select',['SMALL','MEDIUM','LARGE']]])}${groupForm('Sound detection','sound-detection',state,[['soundDetectionSwitch','Detection','boolean'],['soundDetectionAgingType','Schedule type','select',['1','2']],['soundDetectionStartTime','Start','time'],['soundDetectionEndTime','End','time'],['soundDetectionSensitivity','Sensitivity','select',['LOW','MEDIUM','HIGH']]])}${soundControlMarkup(state,controls)}${groupForm('Speaker settings','sound',state,[['soundAgingType','Schedule type','select',['1','2']],['soundStartTime','Start','time'],['soundEndTime','End','time'],['volume','Volume','number']])}${groupForm('Lighting','light',state,[['lightSwitch','Light','boolean'],['lightAgingType','Schedule type','select',['1','2']],['lightingStartTime','Start','time'],['lightingEndTime','End','time'],['filterLedSwitch','Filter LED','boolean']])}${groupForm('Camera','camera',state,[['cameraSwitch','Camera','boolean'],['cameraAgingType','Schedule type','select',['1','2']],['cameraStartTime','Start','time'],['cameraEndTime','End','time'],['resolution','Resolution','select',['P720','P1080']],['nightVision','Night vision','select',['AUTOMATIC','OPEN','CLOSE']]])}${groupForm('Recording','video',state,[['videoRecordSwitch','Record','boolean'],['videoRecordMode','Mode','select',['CONTINUOUS','MOTION_DETECTION']],['videoRecordAgingType','Schedule type','select',['1','2']],['videoRecordStartTime','Start','time'],['videoRecordEndTime','End','time'],['videoWatermarkSwitch','Watermark','boolean']])}${groupForm('Feeding video','feeding-video',state,[['feedingVideoSwitch','Record feeding','boolean'],['enableVideoStartFeedingPlan','Before schedule','boolean'],['beforeFeedingPlanTime','Before minutes','number'],['automaticRecording','Automatic minutes','number'],['enableVideoAfterManualFeeding','After manual feed','boolean'],['afterManualFeedingTime','After minutes','number']])}${groupForm('Bowl','bowl',state,[['bowlMode','Mode','select',['SINGLE_BOWL','DOUBLE_BOWL']]])}</div><div class="read-only">All changes use local MQTT and wait for a feeder ACK. cloudVideoRecordSwitch remains read-only.</div>`}
async function requestControl(deviceId,state,controlName,path){const desired=desiredValues(state),confirmed=confirmedValues(state),current=confirmed[controlName]??desired[controlName];if(typeof current!=='boolean')return;const savingKey=controlName==='soundSwitch'?'soundSaving':'motionSaving';const feedbackKey=controlName==='soundSwitch'?'soundFeedback':'motionFeedback';runtime[savingKey]=true;runtime[feedbackKey]=null;renderDeviceSection(runtime.deviceDetail);try{const response=await fetch(`/api/devices/${encodeURIComponent(deviceId)}/controls/${path}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled:!current})});const payload=await response.json();if(!response.ok)throw new Error(typeof payload.detail==='string'?payload.detail:'Device did not acknowledge the change');runtime[feedbackKey]={error:false,message:'Saved · Device confirmed'};await refresh()}catch(error){runtime[feedbackKey]={error:true,message:error.message||'Device did not acknowledge the change'};renderDeviceSection(runtime.deviceDetail)}finally{runtime[savingKey]=false;if(runtime.deviceDetail)renderDeviceSection(runtime.deviceDetail)}}
function requestSoundSwitch(deviceId,state){return requestControl(deviceId,state,'soundSwitch','sound')}
function requestMotionDetectionSwitch(deviceId,state){return requestControl(deviceId,state,'motionDetectionSwitch','motion')}
function groupPayload(form){const payload={};form.querySelectorAll('input,select').forEach(input=>{const send=input.dataset.known==='true'||input.dataset.dirty==='true';if(input.type==='checkbox'){if(send)payload[input.name]=input.checked}else if(input.type==='number'&&input.value!==''&&send)payload[input.name]=Number(input.value);else if(input.value!==''&&send)payload[input.name]=input.value});for(const key of ['motionDetectionAgingType','soundDetectionAgingType','soundAgingType','lightAgingType','cameraAgingType','videoRecordAgingType'])if(payload[key]!==undefined)payload[key]=Number(payload[key]);return payload}
document.addEventListener('change',event=>{const input=event.target;if((input instanceof HTMLInputElement||input instanceof HTMLSelectElement)&&input.closest('.group-form'))input.dataset.dirty='true'})
async function requestGroup(deviceId,form){const button=form.querySelector('button');button.disabled=true;button.textContent='Saving…';try{const response=await fetch(`/api/devices/${encodeURIComponent(deviceId)}/controls/${form.dataset.controlPath}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(groupPayload(form))});const payload=await response.json();if(!response.ok)throw new Error(typeof payload.detail==='string'?payload.detail:'Device did not acknowledge the change');await refresh()}catch(error){alert(error.message||'Device did not acknowledge the change')}finally{button.disabled=false;button.textContent='Save'}}
function scheduleDays(repeatDay){if(!Array.isArray(repeatDay)||!repeatDay.every(day=>Number.isInteger(day)&&day>=1&&day<=7))return '—';const days=[...new Set(repeatDay)].sort((a,b)=>a-b);if(days.length===7)return 'Every day';if(days.length===5&&days.every((day,index)=>day===index+1))return 'Mon–Fri';const labels=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];return days.map(day=>labels[day-1]).join(', ')}
function reportedValues(state){return Object.fromEntries((state.reported||[]).map(item=>[item.key,item.value]))}
function effectiveValues(state){return {...desiredValues(state),...reportedValues(state),...confirmedValues(state)}}
function known(values,key){return Object.hasOwn(values,key)}
function inputState(values,key){return `data-known="${known(values,key)?'true':'false'}" data-control-field="${escapeHtml(key)}"`}
function checkboxRow(values,key,label,disabled=false){return `<div class="setting-row"><label for="${escapeHtml(key)}">${escapeHtml(label)}</label><input id="${escapeHtml(key)}" name="${escapeHtml(key)}" type="checkbox" ${inputState(values,key)} ${values[key]===true?'checked':''} ${disabled?'disabled':''}></div>`}
function selectField(values,key,label,options,disabled=false){const selected=values[key];const placeholder=known(values,key)?'':'<option value="" selected disabled>Select…</option>';return `<div class="field"><label class="field-label" for="${escapeHtml(key)}">${escapeHtml(label)}</label><select id="${escapeHtml(key)}" name="${escapeHtml(key)}" ${inputState(values,key)} ${disabled?'disabled':''}>${placeholder}${options.map(([value,text])=>`<option value="${escapeHtml(value)}" ${selected===value?'selected':''}>${escapeHtml(text)}</option>`).join('')}</select></div>`}
function numberField(values,key,label,min,max,disabled=false){const value=known(values,key)?values[key]:'';return `<div class="field"><label class="field-label" for="${escapeHtml(key)}">${escapeHtml(label)}</label><input id="${escapeHtml(key)}" name="${escapeHtml(key)}" type="number" min="${min}" max="${max}" value="${escapeHtml(value)}" ${inputState(values,key)} ${disabled?'disabled':''}></div>`}
function timeField(values,key,label,disabled=false){const value=known(values,key)?values[key]:'';return `<div class="field"><label class="field-label" for="${escapeHtml(key)}">${escapeHtml(label)}</label><input id="${escapeHtml(key)}" name="${escapeHtml(key)}" type="time" value="${escapeHtml(value)}" ${inputState(values,key)} ${disabled?'disabled':''}></div>`}
function timeRange(values,start,end,disabled=false){return `<div class="field-row">${timeField(values,start,'Start',disabled)}${timeField(values,end,'End',disabled)}</div>`}
function conditional(condition,content){return `<div class="conditional" data-show-when="${escapeHtml(condition)}">${content}</div>`}
function sourceBadge(state,keys){const desired=desiredValues(state),local=confirmedValues(state);const differs=keys.some(key=>known(local,key)&&known(desired,key)&&local[key]!==desired[key]);if(differs)return '<span class="source-badge diverged">Local · cloud differs</span>';if(keys.some(key=>known(local,key)))return '<span class="source-badge local">Local confirmed</span>';return '<span class="source-badge">Cloud / device</span>'}
function settingCard(title,path,primary,content,state,controls,keys){const capability=controls?.[primary]||{};const disabled=!(capability.writable&&capability.device_online&&!capability.pending)||runtime.controlSaving[path]===true;const feedback=runtime.controlFeedback[path];const message=feedback?`<div class="status-message ${feedback.error?'error':'success'}">${escapeHtml(feedback.message)}</div>`:'<div class="status-message">Changes are sent only after feeder ACK.</div>';return `<article class="card setting-card"><div class="card-head"><h2>${escapeHtml(title)}</h2>${sourceBadge(state,keys)}</div><form class="setting-form control-form" data-control-path="${escapeHtml(path)}" data-primary="${escapeHtml(primary)}" data-disabled="${disabled?'true':'false'}"><fieldset ${disabled?'disabled':''}>${content}</fieldset><div class="setting-actions"><div>${message}</div><button class="save-button" type="submit" ${disabled?'disabled':''}>${runtime.controlSaving[path]?'Saving…':'Save'}</button></div></form></article>`}
function radioChoice(values,key,label,options,disabled=false){const current=values[key];return `<div class="field"><span class="field-label">${escapeHtml(label)}</span><div class="choice-row">${options.map(([value,text])=>`<label><input type="radio" name="${escapeHtml(key)}" value="${escapeHtml(value)}" ${inputState(values,key)} ${String(current)===String(value)?'checked':''} ${disabled?'disabled':''}>${escapeHtml(text)}</label>`).join('')}</div></div>`}
function controlsMarkup(state,controls){const values=effectiveValues(state);const motion=settingCard('Motion detection','motion','motionDetectionSwitch',`${checkboxRow(values,'motionDetectionSwitch','Enable motion detection')}${conditional('motionDetectionSwitch:true',`${selectField(values,'motionDetectionAgingType','Schedule',[['1','All day'],['2','Custom']])}${conditional('motionDetectionAgingType:2',timeRange(values,'motionDetectionStartTime','motionDetectionEndTime'))}${selectField(values,'motionDetectionSensitivity','Sensitivity',[['LOW','Low'],['MEDIUM','Medium'],['HIGH','High']])}${selectField(values,'motionDetectionRange','Detection range',[['SMALL','Small'],['MEDIUM','Medium'],['LARGE','Large']])}`)}`,state,controls,['motionDetectionSwitch','motionDetectionAgingType','motionDetectionStartTime','motionDetectionEndTime','motionDetectionSensitivity','motionDetectionRange']);const soundDetection=settingCard('Sound detection','sound-detection','soundDetectionSwitch',`${checkboxRow(values,'soundDetectionSwitch','Enable sound detection')}${conditional('soundDetectionSwitch:true',`${selectField(values,'soundDetectionAgingType','Schedule',[['1','All day'],['2','Custom']])}${conditional('soundDetectionAgingType:2',timeRange(values,'soundDetectionStartTime','soundDetectionEndTime'))}${selectField(values,'soundDetectionSensitivity','Sensitivity',[['LOW','Low'],['MEDIUM','Medium'],['HIGH','High']])}`)}`,state,controls,['soundDetectionSwitch','soundDetectionAgingType','soundDetectionStartTime','soundDetectionEndTime','soundDetectionSensitivity']);const speaker=settingCard('Speaker','sound','soundSwitch',`${checkboxRow(values,'soundSwitch','Enable device sound')}${conditional('soundSwitch:true',`<div class="field"><label class="field-label" for="volume">Volume</label><div class="range-row"><input id="volume" name="volume" type="range" min="0" max="100" value="${escapeHtml(known(values,'volume')?values.volume:50)}" ${inputState(values,'volume')}><output data-range-output="volume">${escapeHtml(known(values,'volume')?values.volume:50)}%</output></div></div>${selectField(values,'soundAgingType','Schedule',[['1','All day'],['2','Custom']])}${conditional('soundAgingType:2',timeRange(values,'soundStartTime','soundEndTime'))}`)}`,state,controls,['soundSwitch','volume','soundAgingType','soundStartTime','soundEndTime']);const lighting=settingCard('Lighting','light','lightSwitch',`${checkboxRow(values,'lightSwitch','Enable light')}${checkboxRow(values,'filterLedSwitch','Filter LED')}${conditional('lightSwitch:true',`${selectField(values,'lightAgingType','Schedule',[['1','All day'],['2','Custom']])}${conditional('lightAgingType:2',timeRange(values,'lightingStartTime','lightingEndTime'))}`)}`,state,controls,['lightSwitch','filterLedSwitch','lightAgingType','lightingStartTime','lightingEndTime']);const camera=settingCard('Camera','camera','cameraSwitch',`${checkboxRow(values,'cameraSwitch','Enable camera')}${conditional('cameraSwitch:true',`${selectField(values,'cameraAgingType','Schedule',[['1','All day'],['2','Custom']])}${conditional('cameraAgingType:2',timeRange(values,'cameraStartTime','cameraEndTime'))}${selectField(values,'resolution','Resolution',[['P720','720p'],['P1080','1080p']])}${selectField(values,'nightVision','Night vision',[['AUTOMATIC','Automatic'],['OPEN','Always on'],['CLOSE','Off']])}`)}`,state,controls,['cameraSwitch','cameraAgingType','cameraStartTime','cameraEndTime','resolution','nightVision']);const recording=settingCard('Recording','video','videoRecordSwitch',`${checkboxRow(values,'videoRecordSwitch','Enable local recording')}${conditional('videoRecordSwitch:true',`${selectField(values,'videoRecordMode','Mode',[['CONTINUOUS','Continuous'],['MOTION_DETECTION','Motion detection']])}${selectField(values,'videoRecordAgingType','Schedule',[['1','All day'],['2','Custom']])}${conditional('videoRecordAgingType:2',timeRange(values,'videoRecordStartTime','videoRecordEndTime'))}${checkboxRow(values,'videoWatermarkSwitch','Watermark')}`)}<div class="setting-row"><span class="field-label">Cloud recording</span><span class="source-badge">Unavailable · read-only</span></div>`,state,controls,['videoRecordSwitch','videoRecordMode','videoRecordAgingType','videoRecordStartTime','videoRecordEndTime','videoWatermarkSwitch']);const feedingVideo=settingCard('Feeding video','feeding-video','feedingVideoSwitch',`${checkboxRow(values,'feedingVideoSwitch','Enable feeding video')}${conditional('feedingVideoSwitch:true',`${checkboxRow(values,'enableVideoStartFeedingPlan','Start before scheduled feeding')}${conditional('enableVideoStartFeedingPlan:true',numberField(values,'beforeFeedingPlanTime','Minutes',1,5))}${numberField(values,'automaticRecording','Automatic recording duration',1,5)}${checkboxRow(values,'enableVideoAfterManualFeeding','Record after manual feeding')}${conditional('enableVideoAfterManualFeeding:true',numberField(values,'afterManualFeedingTime','Minutes',1,5))}`)}`,state,controls,['feedingVideoSwitch','enableVideoStartFeedingPlan','beforeFeedingPlanTime','automaticRecording','enableVideoAfterManualFeeding','afterManualFeedingTime']);const bowl=settingCard('Bowl configuration','bowl','bowlMode',radioChoice(values,'bowlMode','Bowl mode',[['SINGLE_BOWL','Single bowl'],['DOUBLE_BOWL','Double bowl']]),state,controls,['bowlMode']);return `<div class="setting-grid">${motion}${soundDetection}${speaker}${lighting}${camera}${recording}${feedingVideo}${bowl}</div>`}
function readControlValue(form,key){const elements=[...form.querySelectorAll(`[name="${CSS.escape(key)}"]`)];if(!elements.length)return undefined;const first=elements[0];if(first instanceof HTMLInputElement&&first.type==='checkbox')return first.checked;if(first instanceof HTMLInputElement&&first.type==='radio')return elements.find(element=>element.checked)?.value;return first.value}
function updateControlConditions(form){form.querySelectorAll('[data-show-when]').forEach(section=>{const [key,expected]=section.dataset.showWhen.split(':');section.classList.toggle('hidden',String(readControlValue(form,key))!==expected)});form.querySelectorAll('input[type=range]').forEach(input=>{const output=form.querySelector(`[data-range-output="${CSS.escape(input.name)}"]`),value=`${input.value}%`;if(output&&output.textContent!==value)output.textContent=value})}
function controlDraftKey(deviceId,path){return `${deviceId}:${path}`}
function updateControlDraft(form,input){const deviceId=currentDeviceId(),path=form.dataset.controlPath;if(!deviceId||!path||!input.name)return;const key=controlDraftKey(deviceId,path),draft=runtime.controlDrafts[key]||{};if(input instanceof HTMLInputElement&&input.type==='radio'){if(!input.checked)return;draft[input.name]=input.value}else if(input instanceof HTMLInputElement&&input.type==='checkbox')draft[input.name]=input.checked;else if(input instanceof HTMLInputElement&&(input.type==='number'||input.type==='range'))draft[input.name]=Number(input.value);else draft[input.name]=input.value;runtime.controlDrafts[key]=draft}
function restoreControlDrafts(target,deviceId){target.querySelectorAll('.control-form').forEach(form=>{const draft=runtime.controlDrafts[controlDraftKey(deviceId,form.dataset.controlPath)];if(!draft)return;Object.entries(draft).forEach(([name,value])=>{const elements=[...form.querySelectorAll(`[name="${CSS.escape(name)}"]`)];elements.forEach(element=>{if(element instanceof HTMLInputElement&&element.type==='checkbox'){element.checked=value===true;element.dataset.dirty='true'}else if(element instanceof HTMLInputElement&&element.type==='radio'){element.checked=String(value)===element.value;if(element.checked)element.dataset.dirty='true'}else{element.value=String(value);element.dataset.dirty='true'}})});updateControlConditions(form)})}
function controlPayload(form){const payload={};form.querySelectorAll('[data-control-field]').forEach(input=>{if(input.dataset.dirty!=='true')return;if(input instanceof HTMLInputElement&&input.type==='checkbox')payload[input.name]=input.checked;else if(input instanceof HTMLInputElement&&input.type==='radio'){if(input.checked)payload[input.name]=input.value}else if(input.value!=='')payload[input.name]=input.type==='number'||input.type==='range'?Number(input.value):input.value});for(const key of ['motionDetectionAgingType','soundDetectionAgingType','soundAgingType','lightAgingType','cameraAgingType','videoRecordAgingType'])if(payload[key]!==undefined)payload[key]=Number(payload[key]);return payload}
async function requestControlForm(deviceId,form){const path=form.dataset.controlPath,payload=controlPayload(form);if(!Object.keys(payload).length){runtime.controlFeedback[path]={error:true,message:'No changes to save.'};renderDeviceSection(runtime.deviceDetail);return}runtime.controlSaving[path]=true;runtime.controlFeedback[path]={error:false,message:'Saving… waiting for feeder ACK.'};renderDeviceSection(runtime.deviceDetail);try{const response=await fetch(`/api/devices/${encodeURIComponent(deviceId)}/controls/${path}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const body=await response.json();if(!response.ok)throw new Error(typeof body.detail==='string'?body.detail:'Device did not acknowledge the change');delete runtime.controlDrafts[controlDraftKey(deviceId,path)];runtime.controlSaving[path]=false;runtime.controlFeedback[path]={error:false,message:'Saved · feeder confirmed.'};await refresh()}catch(error){runtime.controlSaving[path]=false;runtime.controlFeedback[path]={error:true,message:error.message||'Device did not acknowledge the change'};renderDeviceSection(runtime.deviceDetail)}}
function handleControlDraftInput(input){const form=input.closest('.control-form');if(!form)return;input.dataset.dirty='true';updateControlDraft(form,input);updateControlConditions(form)}
document.addEventListener('input',event=>{const input=event.target;if(input instanceof HTMLInputElement||input instanceof HTMLSelectElement)handleControlDraftInput(input)})
document.addEventListener('change',event=>{const input=event.target;if(input instanceof HTMLInputElement||input instanceof HTMLSelectElement)handleControlDraftInput(input)})
document.addEventListener('submit',event=>{const form=event.target;if(!(form instanceof HTMLFormElement)||!form.classList.contains('control-form'))return;event.preventDefault();const deviceId=currentDeviceId();if(deviceId)requestControlForm(deviceId,form)})
function scheduleRepeatMode(plan){const days=Array.isArray(plan.repeatDay)?[...new Set(plan.repeatDay.filter(day=>Number.isInteger(day)&&day>=1&&day<=7))]:[];if(!days.length)return 'never';return days.length===7?'every':'custom'}
function scheduleSource(plan){return plan.source==='local'?'Local MQTT':'Cloud plan'}
function schedulePlanCard(plan){const mode=scheduleRepeatMode(plan),audio=plan.enableAudio?`Sound ×${escapeHtml(plan.audioTimes??1)}`:'No sound';const disable=mode==='never'?'':'<button type="button" data-schedule-action="disable">Disable</button>';return `<article class="plan-card" data-plan-id="${escapeHtml(plan.planId)}"><div class="card-head"><div class="plan-time">${escapeHtml(plan.executionTime)}</div><span class="source-badge ${plan.source==='local'?'local':''}">${escapeHtml(scheduleSource(plan))}</span></div><div class="plan-meta"><span>${escapeHtml(plan.grainNum)} portion${Number(plan.grainNum)===1?'':'s'}</span><span>${escapeHtml(scheduleDays(plan.repeatDay))}</span><span>${audio}</span></div><div class="plan-actions"><button type="button" data-schedule-action="edit">Edit</button>${disable}<button class="danger" type="button" data-schedule-action="delete">Delete</button></div></article>`}
function daySelector(selected){const labels=[['1','Mon'],['2','Tue'],['3','Wed'],['4','Thu'],['5','Fri'],['6','Sat'],['7','Sun']];return `<div class="day-selector" data-show-when="repeatMode:custom">${labels.map(([value,label])=>`<label><input type="checkbox" name="repeatDay" value="${value}" ${selected.has(Number(value))?'checked':''}>${label}</label>`).join('')}</div>`}
function scheduleDraftFromPlan(plan={repeatDay:[1,2,3,4,5,6,7]}){const days=Array.isArray(plan.repeatDay)?[...new Set(plan.repeatDay.filter(day=>Number.isInteger(day)&&day>=1&&day<=7))].sort((left,right)=>left-right):[];return {executionTime:typeof plan.executionTime==='string'?plan.executionTime:'07:30',grainNum:Number.isInteger(plan.grainNum)?plan.grainNum:1,enableAudio:plan.enableAudio===true,audioTimes:Number.isInteger(plan.audioTimes)?plan.audioTimes:1,repeatMode:days.length===7?'every':days.length?'custom':'never',selectedDays:days}}
function scheduleDraftDays(draft){return draft.repeatMode==='every'?[1,2,3,4,5,6,7]:draft.repeatMode==='custom'?[...new Set(draft.selectedDays||[])].filter(day=>Number.isInteger(day)&&day>=1&&day<=7).sort((left,right)=>left-right):[]}
function scheduleEditorMarkup(editor){if(!editor)return '';const draft=editor.draft,plan={...draft,planId:editor.planId,repeatDay:scheduleDraftDays(draft)},days=new Set(draft.selectedDays||[]),feedback=runtime.scheduleFeedback;const title=editor.mode==='create'?'Create feeding plan':'Edit feeding plan';const action=editor.mode==='create'?'Create':'Save';const status=feedback?`<div class="status-message ${feedback.error?'error':'success'}">${escapeHtml(feedback.message)}</div>`:'<div class="status-message">Changes are applied after feeder ACK.</div>';return `<form class="schedule-form schedule-editor" data-mode="${escapeHtml(editor.mode)}" ${editor.planId===null?'':`data-plan-id="${escapeHtml(editor.planId)}"`}><h3>${title}</h3><div class="field-row">${timeField(plan,'executionTime','Time')}${numberField(plan,'grainNum','Portions',1,48)}</div>${checkboxRow(plan,'enableAudio','Play sound')}${conditional('enableAudio:true',numberField(plan,'audioTimes','Audio repetitions',1,5))}${radioChoice({repeatMode:draft.repeatMode},'repeatMode','Repeat',[['every','Every day'],['custom','Custom days'],['never','Never']])}${daySelector(days)}<div class="setting-actions"><div>${status}</div><div class="toolbar"><button type="button" data-schedule-action="cancel">Cancel</button><button class="save-button" type="submit">${action}</button></div></div></form>`}
function scheduleMarkup(state){const plans=(state.schedule_plans||[]).map(entry=>({...entry.plan,source:entry.source}));const editor=scheduleEditorMarkup(runtime.scheduleEditor);const list=plans.length?`<div class="plan-list">${plans.map(schedulePlanCard).join('')}</div>`:'<div class="empty-plan">No feeding plans known yet.</div>';return `<div class="info-box"><strong>Local MQTT schedules</strong>Plans created or modified here are applied directly to the feeder. They are not written to PETLIBRO Cloud and may not appear in the official app. Persisted plans are automatically restored when the feeder reconnects.</div><div class="schedule-toolbar"><h3>Existing plans</h3><button class="save-button" type="button" data-schedule-action="create">+ Create plan</button></div>${editor}${list}`}
function updateScheduleDraft(form){const editor=runtime.scheduleEditor;if(!editor)return;const repeatMode=readControlValue(form,'repeatMode');editor.draft={executionTime:readControlValue(form,'executionTime'),grainNum:Number(readControlValue(form,'grainNum')),enableAudio:readControlValue(form,'enableAudio')===true,audioTimes:Number(readControlValue(form,'audioTimes')||1),repeatMode:['custom','never'].includes(repeatMode)?repeatMode:'every',selectedDays:[...form.querySelectorAll('input[name="repeatDay"]:checked')].map(input=>Number(input.value)).filter(Number.isInteger)}}
function schedulePayload(form){updateScheduleDraft(form);const draft=runtime.scheduleEditor?.draft;return draft?{executionTime:draft.executionTime,grainNum:draft.grainNum,enableAudio:draft.enableAudio,audioTimes:draft.audioTimes,repeatDay:scheduleDraftDays(draft)}:{executionTime:readControlValue(form,'executionTime'),grainNum:Number(readControlValue(form,'grainNum')),enableAudio:readControlValue(form,'enableAudio')===true,audioTimes:Number(readControlValue(form,'audioTimes')||1),repeatDay:[]}}
function updateScheduleConditions(form){updateControlConditions(form)}
async function requestScheduleEditor(deviceId,form){const mode=form.dataset.mode,path=mode==='create'?'':`/${encodeURIComponent(form.dataset.planId)}`,method=mode==='create'?'POST':'PATCH';runtime.scheduleFeedback={error:false,message:'Saving… waiting for feeder ACK.'};renderDeviceSection(runtime.deviceDetail);try{const response=await fetch(`/api/devices/${encodeURIComponent(deviceId)}/schedule${path}`,{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(schedulePayload(form))});const body=await response.json();if(!response.ok)throw new Error(typeof body.detail==='string'?body.detail:'Device did not acknowledge the schedule change');runtime.scheduleEditor=null;runtime.scheduleFeedback={error:false,message:'Saved · feeder confirmed.'};await refresh()}catch(error){runtime.scheduleFeedback={error:true,message:error.message||'Device did not acknowledge the schedule change'};renderDeviceSection(runtime.deviceDetail)}}
async function requestScheduleAction(deviceId,planId,action){const path=`/${encodeURIComponent(planId)}`;let method='PATCH',payload={repeatDay:[]};if(action==='delete'){if(!window.confirm('Delete this feeding plan? This cannot be undone locally.'))return;method='DELETE';payload=null}runtime.scheduleFeedback={error:false,message:action==='delete'?'Deleting… waiting for feeder ACK.':'Disabling… waiting for feeder ACK.'};renderDeviceSection(runtime.deviceDetail);try{const response=await fetch(`/api/devices/${encodeURIComponent(deviceId)}/schedule${path}`,{method,headers:{'Content-Type':'application/json'},body:method==='DELETE'?undefined:JSON.stringify(payload)});const body=await response.json();if(!response.ok)throw new Error(typeof body.detail==='string'?body.detail:'Device did not acknowledge the schedule change');runtime.scheduleFeedback={error:false,message:action==='delete'?'Deleted · feeder confirmed.':'Disabled · feeder confirmed.'};await refresh()}catch(error){runtime.scheduleFeedback={error:true,message:error.message||'Device did not acknowledge the schedule change'};renderDeviceSection(runtime.deviceDetail)}}
function handleScheduleDraftInput(input){const form=input.closest('.schedule-editor');if(!form)return;updateScheduleDraft(form);updateScheduleConditions(form)}
document.addEventListener('input',event=>{const input=event.target;if(input instanceof HTMLInputElement||input instanceof HTMLSelectElement)handleScheduleDraftInput(input)})
document.addEventListener('change',event=>{const input=event.target;if(input instanceof HTMLInputElement||input instanceof HTMLSelectElement)handleScheduleDraftInput(input)})
document.addEventListener('submit',event=>{const form=event.target;if(!(form instanceof HTMLFormElement)||!form.classList.contains('schedule-editor'))return;event.preventDefault();const deviceId=currentDeviceId();if(deviceId)requestScheduleEditor(deviceId,form)})
document.addEventListener('click',event=>{const button=event.target.closest('[data-schedule-action]');if(!button)return;const deviceId=currentDeviceId();if(!deviceId)return;const action=button.dataset.scheduleAction,planCard=button.closest('[data-plan-id]');if(action==='create'){runtime.scheduleEditor={mode:'create',planId:null,draft:scheduleDraftFromPlan()};runtime.scheduleFeedback=null;renderDeviceSection(runtime.deviceDetail)}else if(action==='edit'&&planCard){const plan=(runtime.deviceDetail.state.schedule_plans||[]).find(entry=>String(entry.plan.planId)===String(planCard.dataset.planId));if(plan){runtime.scheduleEditor={mode:'edit',planId:plan.planId,draft:scheduleDraftFromPlan(plan.plan)};runtime.scheduleFeedback=null;renderDeviceSection(runtime.deviceDetail)}}else if(action==='cancel'){runtime.scheduleEditor=null;runtime.scheduleFeedback=null;renderDeviceSection(runtime.deviceDetail)}else if((action==='disable'||action==='delete')&&planCard)requestScheduleAction(deviceId,planCard.dataset.planId,action)})
const dynamicFormObserver=new MutationObserver(()=>{document.querySelectorAll('.control-form').forEach(updateControlConditions);document.querySelectorAll('.schedule-editor').forEach(updateScheduleConditions)});dynamicFormObserver.observe(byId('device-page'),{childList:true,subtree:true})
function cameraMetadata(state){const safeKeys=new Set(['tutkP2pRegion','motionDetectionSwitch','motionDetectionSensitivity','motionDetectionRange','motionDetectionAgingType','soundDetectionSwitch','soundDetectionSensitivity','soundDetectionAgingType','soundSwitch']);const values={};for(const item of [...(state.reported||[]),...(state.desired||[])])if(safeKeys.has(item.key))values[item.key]=item.value;return values}
function cameraMarkup(state,camera){const metadata=cameraMetadata(state),status=camera||runtime.deviceDetail?.camera||{},rows=Object.entries(metadata).map(([key,value])=>[key,scalar(value)]);const reason=status.reason?String(status.reason).replaceAll('_',' '):'—';const live=status.available&&status.webrtc?'<div class="camera-placeholder"><div><strong>Player unavailable in this POC</strong>The PLAF203 TUTK AV protocol is not yet confirmed.</div></div>':'<div class="camera-placeholder"><div><strong>Live stream unavailable</strong>The camera bridge has learned registrations only; it does not start an unverified PLAF203 media session.</div></div>';return `${card('Live view',live)}${card('Camera bridge',kv([['Bridge',statusBadge(status.bridge_reachable?'ONLINE':'OFFLINE')],['UID learned',escapeHtml(status.uid_learned?'Yes':'No')],['Bridge registration',escapeHtml(status.bridge_registered?'Registered':'Not registered')]]))}${card('go2rtc stream status',kv([['go2rtc',statusBadge(status.go2rtc_reachable?'ONLINE':'OFFLINE')],['Camera source',statusBadge(status.configured?'ONLINE':'OFFLINE',status.configured?'Configured':'Not configured')],['Stream',escapeHtml(status.stream)],['Stream online',escapeHtml(status.online?'Yes':'No')],['WebRTC player',escapeHtml(status.webrtc?'Available':'Unavailable')],['Reason',escapeHtml(reason)]]))}${card('Known camera diagnostics',rows.length?kv(rows):'<div class="empty">No safe camera or P2P metadata has been observed.</div>')}${Object.keys(metadata).length?`<div class="details">${rawButton(metadata,'View visible camera metadata')}</div>`:''}`}
function deviceOverviewMarkup(detail){const device=detail.device,up=detail.cloud.metrics.upstream,c=up.counters||{},queues=detail.queues,state=detail.state,ntp=detail.ntp,responder=detail.local_responder;return `<div class="grid wide">${card('Device',kv([['Model',escapeHtml(device.product_id)],['Status',statusBadge(device.status)],['Local',statusBadge(device.local_state==='LOCAL_ONLINE'?'ONLINE':'OFFLINE')],['IP',escapeHtml(device.ip)],['MAC',escapeHtml(device.mac)],['Firmware',escapeHtml(device.firmware)],['Hardware',escapeHtml(device.hardware_version)],['RSSI',rssiMarkup(device.rssi)],['Last heartbeat',escapeHtml(formatAge(device.last_heartbeat_ts))],['Last seen',escapeHtml(formatAge(device.last_seen_at))],['Username',escapeHtml(device.username)],['Identity TTL',escapeHtml(formatDuration(device.ttl_remaining_seconds))]]))}${card('Cloud',kv([['PETLIBRO state',statusBadge(up.state)],['Current session',escapeHtml(formatDuration(up.current_online_duration_seconds))],['Previous session',escapeHtml(formatDuration(up.previous_session_duration_seconds))],['Availability 15m',escapeHtml(formatPercent(up.availability?.['15m']))],['Availability 1h',escapeHtml(formatPercent(up.availability?.['1h']))],['Availability 24h',escapeHtml(formatPercent(up.availability?.['24h']))],['Sessions lost',escapeHtml(c.sessions_lost||0)],['Connect attempts',escapeHtml(c.connect_attempts||0)],['CONNACK timeouts',escapeHtml(c.connack_timeouts||0)],['TCP failures',escapeHtml(c.tcp_connect_failures||0)]]))}${card('Queues',kv([['Device → Cloud',`${escapeHtml(queues.device_to_cloud.pending)} pending`,queues.device_to_cloud.pending?'warning-value':'ok-value'],['Cloud → Device',`${escapeHtml(queues.cloud_to_device.pending)} pending`,queues.cloud_to_device.pending?'warning-value':'ok-value'],['Oldest device → cloud',escapeHtml(formatDuration(queues.device_to_cloud.oldest_age_seconds))],['Oldest cloud → device',escapeHtml(formatDuration(queues.cloud_to_device.oldest_age_seconds))]]))}${card('State shadow',kv([['Reported values',escapeHtml(state.counts.reported)],['Cloud desired',escapeHtml(state.counts.desired)],['Raw messages',escapeHtml(state.counts.raw_messages)],['Feeding plan',state.feeding_plans.complete?'<span class="ok-value">Cached ✓</span>':'<span class="muted">Not cached</span>']]))}${card('NTP',kv([['Last request',escapeHtml(formatTimestamp(ntp.last_request?.updated_at))],['Requests observed',escapeHtml(ntp.requests_observed)],['Cloud responses',escapeHtml(ntp.cloud_ntp_sync_responses)],['Local responses',escapeHtml(ntp.local_ntp_responses)],['Local fallback',escapeHtml(formatBoolean(ntp.local_fallback_enabled))]]))}${card('Local responder',kv([['Global',escapeHtml(formatBoolean(responder.enabled))],['NTP',escapeHtml(formatBoolean(responder.ntp_enabled))],['Config',escapeHtml(formatBoolean(responder.config_enabled))],['Feeding plan',escapeHtml(formatBoolean(responder.feeding_plan_enabled))]]))}</div>${card('Device timeline',timelineMarkup(detail.cloud.events,'No upstream events for this device yet.'))}`}
function clearEditingDrafts(){runtime.controlDrafts={};runtime.scheduleEditor=null;runtime.scheduleFeedback=null}
function renderDeviceSection(detail){const target=byId('device-view');const deviceId=currentDeviceId();if(!target||!deviceId)return;if(runtime.deviceTab==='overview')target.innerHTML=deviceOverviewMarkup(detail);else if(runtime.deviceTab==='controls'){target.innerHTML=`<div class="section-title"><h2>Controls</h2><span class="muted">Device ACK required</span></div>${controlsMarkup(detail.state,detail.controls)}`;restoreControlDrafts(target,deviceId);const soundToggle=byId('sound-switch-toggle');if(soundToggle)soundToggle.onclick=()=>requestSoundSwitch(deviceId,detail.state);const motionToggle=byId('motion-detection-switch-toggle');if(motionToggle)motionToggle.onclick=()=>requestMotionDetectionSwitch(deviceId,detail.state);target.querySelectorAll('.group-form').forEach(form=>form.onsubmit=event=>{event.preventDefault();requestGroup(deviceId,form)})}else if(runtime.deviceTab==='schedule'){target.innerHTML=`<div class="section-title"><h2>Schedule</h2><span class="muted">Local MQTT</span></div>${scheduleMarkup(detail.state)}`;target.querySelectorAll('.schedule-editor').forEach(updateScheduleConditions)}else if(runtime.deviceTab==='camera')target.innerHTML=`<div class="section-title"><h2>Camera</h2><span class="muted">No network traffic generated</span></div>${cameraMarkup(detail.state)}`;else if(runtime.deviceTab==='state')target.innerHTML=`<div class="section-title"><h2>State shadow</h2><span class="muted">Last-known values only</span></div>${stateMarkup(detail.state)}`;else if(runtime.deviceTab==='logs'){target.innerHTML=`<div class="section-title"><h2>Logs</h2><span class="muted">Live SSE stream · device scoped</span></div>${logPanel('device-log',deviceId)}`;initializeLogControls('device-log',deviceId);runtime.logs.forEach(item=>{addFilterOption('device-log','component',item.component);addFilterOption('device-log','cmd',item.cmd)});renderLogLines('device-log',deviceId)}bindRawButtons()}
function renderDevicePage(detail){if(runtime.draftDeviceId!==detail.device.device_id){clearEditingDrafts();runtime.draftDeviceId=detail.device.device_id}runtime.deviceDetail=detail;byId('global-pages').classList.add('hidden');const target=byId('device-page');target.classList.remove('hidden');const device=detail.device;target.innerHTML=`<a class="back-link" href="/devices" data-route="/devices">← Devices</a><div class="device-page-title"><div><h2>${escapeHtml(device.product_id)}</h2><div class="device-id">${escapeHtml(device.device_id)}</div></div><div class="status">${statusBadge(device.local_state==='LOCAL_ONLINE'?'ONLINE':'OFFLINE','Local')}${statusBadge(device.bridged?device.cloud_state:'NOT_BRIDGED','PETLIBRO')}${device.rssi===null||device.rssi===undefined?'':rssiMarkup(device.rssi)}</div></div><div class="muted">${[device.firmware,device.ip].filter(value=>value!==null&&value!==undefined&&value!=='').map(escapeHtml).join(' · ')}</div><div class="subnav">${DEVICE_TABS.map(tab=>`<button type="button" data-device-tab="${tab}" class="${runtime.deviceTab===tab?'active':''}">${escapeHtml(tab[0].toUpperCase()+tab.slice(1))}</button>`).join('')}</div><section id="device-view"></section>`;target.querySelectorAll('[data-device-tab]').forEach(button=>button.onclick=()=>{const nextTab=button.dataset.deviceTab;if(nextTab!==runtime.deviceTab)clearEditingDrafts();runtime.deviceTab=nextTab;history.replaceState(null,'',`#${runtime.deviceTab}`);renderDevicePage(runtime.deviceDetail)});renderDeviceSection(detail)}
async function syncDeviceList(){const devices=fleetData(await fetchJson('/api/devices'));runtime.devices=devices.devices;if(!runtime.selected&&runtime.devices.length)runtime.selected=runtime.devices[0].device_id;return devices}
function renderFailure(error){console.error(error);const deviceId=currentDeviceId();const section=deviceId?byId('device-page'):byId(runtime.active);if(!section)return;if(deviceId){byId('global-pages').classList.add('hidden');section.classList.remove('hidden')}const viewName=deviceId?'device':runtime.active;section.innerHTML=`<div class="section-title"><h2>Failed to render ${escapeHtml(viewName)}</h2></div><div class="empty">The dashboard could not load this view. Check the browser console or relay logs for details.</div>`}
async function refresh(){try{const [status,system]=await Promise.all([fetchJson('/api/status'),fetchJson('/api/system')]);renderHeader(status,system);const deviceId=currentDeviceId();if(deviceId){const detail=await fetchJson(`/api/devices/${encodeURIComponent(deviceId)}`);renderDevicePage(detail);return}byId('global-pages').classList.remove('hidden');byId('device-page').classList.add('hidden');if(runtime.active==='Devices'){renderDevices(await syncDeviceList());return}if(['Queues','State','NTP'].includes(runtime.active)){await syncDeviceList();if(!runtime.selected){byId(runtime.active).innerHTML='<div class="empty">No device known yet.</div>';return}const scope=`device_id=${encodeURIComponent(runtime.selected)}`;if(runtime.active==='Queues')renderQueues(await fetchJson(`/api/queues?limit=100&${scope}`));else if(runtime.active==='State')renderState(await fetchJson(`/api/state?${scope}`));else renderNtp(await fetchJson(`/api/ntp?${scope}`),status);return}if(runtime.active==='Overview')renderOverview(status);else if(runtime.active==='Cloud')renderCloud(await fetchJson('/api/cloud'));else if(runtime.active==='Logs')renderLogs();else if(runtime.active==='System')renderSystem(system,status)}catch(error){byId('header-badges').innerHTML=statusBadge('ERROR','Dashboard');renderFailure(error)}}
byId('raw-close').onclick=()=>byId('raw-modal').close();bindRoutes();loadInitialLogs().catch(console.error);startLogStream();applyRoute();setInterval(refresh,3000);window.addEventListener('popstate',applyRoute);window.addEventListener('hashchange',()=>{const nextTab=deviceTabFromHash();if(nextTab!==runtime.deviceTab)clearEditingDrafts();runtime.deviceTab=nextTab;if(runtime.deviceDetail)renderDevicePage(runtime.deviceDetail)});
</script></body></html>"""

_CAMERA_PLAYER_CSS = r"""
<style>
.camera-player{position:relative;aspect-ratio:16/9;min-height:230px;background:#05080c;border:1px solid #2c3a49;border-radius:8px;overflow:hidden}.camera-player video{display:block;width:100%;height:100%;object-fit:contain;background:#05080c}.camera-player-state{position:absolute;left:10px;bottom:10px;padding:4px 9px;border:1px solid #34485b;border-radius:999px;background:rgba(10,16,22,.78);color:#91a2b3;font-size:12px}.camera-player-state.live{color:#35bf82;border-color:#297354}.camera-player-state.error{color:#ed6b6b;border-color:#875050}
</style>
"""

_CAMERA_PLAYER_JS = r"""
<script>
runtime.cameraPlayer=null;
function cameraPlayerMarkup(status){const ready=status&&status.go2rtc_reachable&&status.bridge_registered;return ready?'<div id="camera-player" class="camera-player"><video id="camera-video" autoplay playsinline muted></video><span id="camera-player-state" class="camera-player-state">Connecting…</span></div>':'<div class="camera-placeholder"><div><strong>Live stream unavailable</strong>Waiting for the local camera bridge and go2rtc registration.</div></div>'}
function cameraMarkup(state,camera){const metadata=cameraMetadata(state),status=camera||runtime.deviceDetail?.camera||{},rows=Object.entries(metadata).map(([key,value])=>[key,scalar(value)]),reason=status.reason?String(status.reason).replaceAll('_',' '):'—';return `${card('Live view',cameraPlayerMarkup(status))}${card('Camera bridge',kv([['Bridge',statusBadge(status.bridge_reachable?'ONLINE':'OFFLINE')],['UID learned',escapeHtml(status.uid_learned?'Yes':'No')],['Bridge registration',escapeHtml(status.bridge_registered?'Registered':'Not registered')],['Media consumers',escapeHtml(status.media_consumers??0)]]))}${card('go2rtc stream status',kv([['go2rtc',statusBadge(status.go2rtc_reachable?'ONLINE':'OFFLINE')],['Camera source',statusBadge(status.configured?'ONLINE':'OFFLINE',status.configured?'Configured':'Pending')],['Stream',escapeHtml(status.stream)],['Stream online',escapeHtml(status.online?'Yes':'No')],['WebRTC player',escapeHtml(status.player_available?'Available':'Connecting on open')],['Reason',escapeHtml(reason)]]))}${card('Known camera diagnostics',rows.length?kv(rows):'<div class="empty">No safe camera or P2P metadata has been observed.</div>')}${Object.keys(metadata).length?`<div class="details">${rawButton(metadata,'View visible camera metadata')}</div>`:''}`}
function setCameraPlayerState(text,kind=''){const state=byId('camera-player-state');if(!state)return;state.textContent=text;state.className=`camera-player-state ${kind}`}
function closeCameraPlayer(){const player=runtime.cameraPlayer;if(!player)return;if(player.retryTimer)clearTimeout(player.retryTimer);if(player.pc)player.pc.close();runtime.cameraPlayer=null}
function completeCameraOffer(pc){return new Promise(resolve=>{if(pc.iceGatheringState==='complete'){resolve(pc.localDescription.sdp);return}const finish=()=>{pc.removeEventListener('icegatheringstatechange',onChange);resolve(pc.localDescription?.sdp||'')};const onChange=()=>{if(pc.iceGatheringState==='complete')finish()};pc.addEventListener('icegatheringstatechange',onChange);setTimeout(finish,2500)})}
function scheduleCameraRetry(deviceId){const player=runtime.cameraPlayer;if(!player||player.retryTimer)return;player.retryTimer=setTimeout(()=>{if(currentDeviceId()!==deviceId||runtime.deviceTab!=='camera')return;closeCameraPlayer();startCameraPlayer(deviceId)},10000)}
async function startCameraPlayer(deviceId){if(runtime.cameraPlayer||currentDeviceId()!==deviceId||runtime.deviceTab!=='camera'||!byId('camera-video'))return;const player={deviceId,pc:null,retryTimer:null};runtime.cameraPlayer=player;setCameraPlayerState('Connecting…');try{const pc=new RTCPeerConnection({bundlePolicy:'max-bundle'});player.pc=pc;const stream=new MediaStream();const video=byId('camera-video');video.srcObject=stream;video.onloadeddata=()=>{if(runtime.cameraPlayer===player)setCameraPlayerState('Live','live')};pc.ontrack=event=>{stream.addTrack(event.track);setCameraPlayerState('Live','live');video.play().catch(()=>{})};pc.onconnectionstatechange=()=>{if(runtime.cameraPlayer!==player)return;if(pc.connectionState==='failed'||pc.connectionState==='disconnected'){setCameraPlayerState('Offline','error');scheduleCameraRetry(deviceId)}else if(pc.connectionState==='closed'){setCameraPlayerState('Offline','error')}};pc.addTransceiver('video',{direction:'recvonly'});const offer=await pc.createOffer();await pc.setLocalDescription(offer);const sdp=await completeCameraOffer(pc);const response=await fetch(`/api/devices/${encodeURIComponent(deviceId)}/camera/webrtc`,{method:'POST',headers:{'Content-Type':'application/sdp'},body:sdp});if(!response.ok)throw new Error(`HTTP ${response.status}`);await pc.setRemoteDescription({type:'answer',sdp:await response.text()});setCameraPlayerState('Connecting…')}catch(error){if(runtime.cameraPlayer!==player)return;setCameraPlayerState('Offline','error');scheduleCameraRetry(deviceId)}}
function updateCameraPlayerStatus(status){if(!runtime.cameraPlayer)return;const state=byId('camera-player-state');if(state&&status&&status.online&&state.textContent==='Connecting…')state.textContent='Connecting…'}
const originalRenderDeviceSection=renderDeviceSection;renderDeviceSection=function(detail){if(runtime.deviceTab!=='camera'){originalRenderDeviceSection(detail);return}const target=byId('device-view'),deviceId=currentDeviceId();if(!target||!deviceId)return;const player=runtime.cameraPlayer;if(player&&player.deviceId===deviceId&&byId('camera-player')){runtime.deviceDetail=detail;updateCameraPlayerStatus(detail.camera);return}target.innerHTML=`<div class="section-title"><h2>Camera</h2><span class="muted">WebRTC via local go2rtc</span></div>${cameraMarkup(detail.state,detail.camera)}`;bindRawButtons();startCameraPlayer(deviceId)};
const originalRenderDevicePage=renderDevicePage;renderDevicePage=function(detail){const player=runtime.cameraPlayer;if(runtime.deviceTab==='camera'&&player&&player.deviceId===detail.device.device_id&&byId('camera-player')){runtime.deviceDetail=detail;updateCameraPlayerStatus(detail.camera);return}if(player)closeCameraPlayer();originalRenderDevicePage(detail)};
const originalClearEditingDrafts=clearEditingDrafts;clearEditingDrafts=function(){closeCameraPlayer();originalClearEditingDrafts()};
</script>
"""

DASHBOARD_HTML = DASHBOARD_HTML.replace("</head>", _CAMERA_PLAYER_CSS + "</head>").replace(
    "</body></html>", _CAMERA_PLAYER_JS + "</body></html>"
)
